const fs = require('fs');
const https = require('https');

const subsPath = '/home/node/.n8n/anime-tracker/subscriptions.json';
const subs = JSON.parse(fs.readFileSync(subsPath, 'utf8'));

function fetchPage(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36' } }, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => resolve(data));
    }).on('error', reject);
  });
}

function fetchImage(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Referer': 'https://voir-anime.to/'
    }}, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks)));
    }).on('error', reject);
  });
}

function postDiscord(webhookUrl, animeName, epNum, epUrl, imageBuffer, imageExt) {
  return new Promise((resolve, reject) => {
    const boundary = '----FormBoundary' + Math.random().toString(36).slice(2);
    const embed = JSON.stringify({
      embeds: [{
        title: `🎌 ${animeName} — Épisode ${epNum} disponible !`,
        url: epUrl,
        color: 0x6c63ff,
        image: { url: `attachment://cover.${imageExt}` },
        fields: [{ name: '🔗 Regarder', value: epUrl }],
        footer: { text: 'VoirAnime Tracker' }
      }]
    });
    const embedPart = `--${boundary}\r\nContent-Disposition: form-data; name="payload_json"\r\nContent-Type: application/json\r\n\r\n${embed}\r\n`;
    const filePart = `--${boundary}\r\nContent-Disposition: form-data; name="files[0]"; filename="cover.${imageExt}"\r\nContent-Type: image/${imageExt}\r\n\r\n`;
    const endPart = `\r\n--${boundary}--\r\n`;
    const body = Buffer.concat([
      Buffer.from(embedPart),
      Buffer.from(filePart),
      imageBuffer,
      Buffer.from(endPart)
    ]);
    const hostname = 'discordapp.com';
    const path = webhookUrl.replace('https://discordapp.com', '');
    const req = https.request({
      hostname, path, method: 'POST',
      headers: {
        'Content-Type': `multipart/form-data; boundary=${boundary}`,
        'Content-Length': body.length
      }
    }, res => { res.on('data', () => {}); res.on('end', resolve); });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

function postDiscordSimple(webhookUrl, animeName, epNum, epUrl) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify({
      embeds: [{
        title: `🎌 ${animeName} — Épisode ${epNum} disponible !`,
        url: epUrl,
        color: 0x6c63ff,
        fields: [{ name: '🔗 Regarder', value: epUrl }],
        footer: { text: 'VoirAnime Tracker' }
      }]
    });
    const hostname = 'discordapp.com';
    const path = webhookUrl.replace('https://discordapp.com', '');
    const req = https.request({
      hostname, path, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }
    }, res => { res.on('data', () => {}); res.on('end', resolve); });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

const report = [];
let changed = false;

for (const sub of subs) {
  try {
    const html = await fetchPage(sub.anime_url);
    const baseSlug = sub.anime_url.replace('https://voir-anime.to/anime/', '').replace(/\/$/, '');
    const escapedSlug = baseSlug.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`href="(https://voir-anime\\.to/anime/${escapedSlug}/[^"]*-(\\d+)-vostfr[^"]*)"`, 'g');

    const episodes = [];
    let m;
    while ((m = regex.exec(html)) !== null) {
      episodes.push({ url: m[1], num: parseInt(m[2]) });
    }

    if (!episodes.length) {
      report.push({ anime: sub.anime_name, status: 'aucun épisode trouvé' });
      continue;
    }

    const maxEp = Math.max(...episodes.map(e => e.num));
    const maxUrl = episodes.find(e => e.num === maxEp).url;
    const last = sub.last_episode || 0;

    if (maxEp <= last) {
      report.push({ anime: sub.anime_name, status: `à jour (ep ${last})` });
      continue;
    }

    const imgMatch = html.match(/<meta property="og:image" content="([^"]+)"/);
    const imageUrl = imgMatch ? imgMatch[1] : '';
    const imageExt = imageUrl ? (imageUrl.split('.').pop().split('?')[0] || 'jpg') : 'jpg';

    let imageBuffer = null;
    if (imageUrl) {
      try { imageBuffer = await fetchImage(imageUrl); } catch(e) {}
    }

    if (imageBuffer) {
      await postDiscord(sub.discord_webhook, sub.anime_name, maxEp, maxUrl, imageBuffer, imageExt);
    } else {
      await postDiscordSimple(sub.discord_webhook, sub.anime_name, maxEp, maxUrl);
    }

    sub.last_episode = maxEp;
    changed = true;
    report.push({ anime: sub.anime_name, status: `notifié ep ${maxEp}` });

  } catch (e) {
    report.push({ anime: sub.anime_name, status: 'erreur: ' + e.message });
  }
}

if (changed) {
  fs.writeFileSync(subsPath, JSON.stringify(subs, null, 2));
}

return [{ json: { checked: subs.length, report } }];
